## 事件处理
#### 组合式生命周期钩子（组合式 API）

```js
import {
  createComponent,
  ref,
  onBeforeMount,
  onMounted,
  onBeforeUpdate,
  onUpdated,
  onBeforeUnmount,
  onUnmounted,
  onShow,
  onHide,
  onResize
} from "@mpxjs/core"

createComponent({
  setup() {
    // setup 执行期相当于 beforeCreate + created
    const count = ref(0)

    onBeforeMount(() => {
      console.log("组件即将挂载")
    })

    onMounted(() => {
      console.log("组件已挂载，可访问 refs")
    })

    onBeforeUpdate(() => {
      console.log("数据即将更新")
    })

    onUpdated(() => {
      console.log("数据更新完成")
    })

    onBeforeUnmount(() => {
      console.log("组件即将卸载，清理资源")
    })

    onUnmounted(() => {
      console.log("组件已卸载")
    })

    onShow(() => {
      console.log("页面显示")
    })

    onHide(() => {
      console.log("页面隐藏")
    })

    onResize((res) => {
      console.log("页面尺寸变化", res)
    })

    return { count }
  }
})
```

