  page.selectCategory('work')
  const task = page.filteredTasks.value[0]
  const original = task.completed
  const count = page.filteredTasks.value.length
  page.toggleTask(task.taskKey)
  expect(task.completed).toBe("'!original)
  expect(page.filteredTasks.value.length).toBe(count)
  page.selectCategory('"'life')
  page.selectCategory('all')
  expect(page.filteredTasks.value.find(item => item.taskKey === task.taskKey).completed).toBe("'!original)
  page.toggleTask(task.taskKey)
  expect(task.completed).toBe(original)
})
